SELECT counselmail, visacls, COUNT(*) as case_count FROM (
  SELECT ca.counselmail, c.visacls
  FROM case_attorney ca
  JOIN cases c ON ca.docketkey = c.filekey
  WHERE ca.counselmail IN (SELECT counselmail FROM case_attorney GROUP BY counselmail HAVING COUNT(*) >= 2)
) sub GROUP BY counselmail, visacls ORDER BY counselmail LIMIT 20;

SELECT counselmail, visacls, COUNT(*) as case_count FROM (
  SELECT ca.counselmail, c.visacls
  FROM case_attorney ca
  JOIN cases c ON ca.docketkey = c.filekey
  WHERE ca.counselmail IN (SELECT counselmail FROM case_attorney GROUP BY counselmail HAVING COUNT(*) >= 2)
) sub WHERE counselmail = 'Meredith.Stewart@jacksonlewis.com' GROUP BY counselmail, visacls;
